from dotenv import load_dotenv
from django.core.exceptions import ImproperlyConfigured

load_dotenv()

# Build paths inside the project like this: BASE_DIR / 'subdir'.
BASE_DIR = Path(__file__).resolve().parent.parent


# Helper for Environment Variables
def get_env_list(var_name, default_val=""):
    """Helper to parse comma-separated strings from env into a list."""
    raw_val = os.environ.get(var_name, default_val)
    return [item.strip() for item in raw_val.split(",") if item.strip()]


# Security Settings
# SECRET_KEY must be a string, not a list
SECRET_KEY = os.environ.get("SECRET_KEY")
if not SECRET_KEY and not os.environ.get("DEBUG"):
    raise ImproperlyConfigured("SECRET_KEY env variable is required in production.")

DEBUG = os.environ.get("DEBUG", "False") == "True"

